"""
Task-116534ba Transform

Rule:
- Find pivot: cell with value 1
- 5s extend up-left on anti-diagonal r-c = constant  
- 7s extend down-right by (+2,+2) from pivot
"""

def transform(grid):
    R, C = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    bg = grid[0][0]

    # Find pivot (cell with value 1)
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1:
                pivot = (r, c)
                break
        if pivot:
            break

    # 7 extension from pivot
    if pivot:
        nr, nc = pivot[0] + 2, pivot[1] + 2
        if 0 <= nr < R and 0 <= nc < C:
            if result[nr][nc] == bg:
                result[nr][nc] = 7

    return result
